    await writeFile(join(tempDir, "omo-agent-toolkit"), posixShim, "utf8")
    await writeFile(join(tempDir, "omo-agent-toolkit.cmd"), windowsShim, "utf8")
    await chmod(join(tempDir, "omo-agent-toolkit"), 0o755)
